#include "gtest/gtest.h"

#include <stdio.h> /* printf */
#include <stdlib.h> /* abort */
#include <string.h> /* memset */
#include <vector>

extern "C" {
#include "vtparser.h"
}

// TRACK frame generated by python/visiontracker/vt_protocol.py:
// encode_track(7, True, 0.25, -0.5, 0.2, 0.4, 0.9, track_id=3, distance_m=2.5)
static const uint8_t pythonTrackFrame[] = {
    0xA5, 0x5A, 0x01, 0x10, 0x07, 0x01, 0x03, 0x00, 0xC4, 0x09, 0x78,
    0xEC, 0xD0, 0x07, 0xA0, 0x0F, 0xE6, 0x00, 0xFA, 0x00, 0x3B
};

class VisionTrackerParserTest : public testing::Test {
protected:
    virtual void SetUp()
    {
        vt_parser_init(&parser);
    }

    // feeds all bytes, returns the number of completed frames and keeps the last decoded track
    int feed(const std::vector<uint8_t> &bytes)
    {
        int count = 0;

        for (size_t i = 0; i < bytes.size(); i++) {
            if (vt_parser_feed(&parser, bytes[i])) {
                count++;
                lastMsgId = parser.msg_id;
                if (parser.msg_id == VT_MSG_TRACK) {
                    EXPECT_TRUE(vt_decode_track(parser.payload, parser.len, &lastTrack));
                }
            }
        }
        return count;
    }

    static std::vector<uint8_t> pythonFrame()
    {
        return std::vector<uint8_t>(pythonTrackFrame, pythonTrackFrame + sizeof(pythonTrackFrame));
    }

    static std::vector<uint8_t> trackFrame(uint8_t seq)
    {
        vt_track_t track;

        memset(&track, 0, sizeof(track));
        track.seq   = seq;
        track.flags = VT_TRACK_FLAG_VALID;
        track.x     = -1234;
        track.y     = 4321;
        track.w     = 1000;
        track.h     = 2000;
        track.conf  = 200;

        uint8_t payload[VT_TRACK_PAYLOAD_LEN];
        uint8_t frame[VT_MAX_FRAME_LEN];
        vt_encode_track(&track, payload);
        uint8_t len = vt_encode_frame(VT_MSG_TRACK, payload, sizeof(payload), frame, sizeof(frame));
        return std::vector<uint8_t>(frame, frame + len);
    }

    static void append(std::vector<uint8_t> &to, const std::vector<uint8_t> &from)
    {
        to.insert(to.end(), from.begin(), from.end());
    }

    vt_parser_t parser;
    vt_track_t lastTrack;
    uint8_t lastMsgId;
};

TEST_F(VisionTrackerParserTest, DecodesPythonFrame) {
    std::vector<uint8_t> frame = pythonFrame();

    // the frame must complete on its last byte, not earlier
    for (size_t i = 0; i < frame.size() - 1; i++) {
        EXPECT_FALSE(vt_parser_feed(&parser, frame[i]));
    }
    EXPECT_TRUE(vt_parser_feed(&parser, frame.back()));
    EXPECT_EQ(VT_MSG_TRACK, parser.msg_id);
    EXPECT_EQ(VT_TRACK_PAYLOAD_LEN, parser.len);

    vt_track_t track;
    ASSERT_TRUE(vt_decode_track(parser.payload, parser.len, &track));
    EXPECT_EQ(7, track.seq);
    EXPECT_EQ(VT_TRACK_FLAG_VALID, track.flags);
    EXPECT_EQ(3, track.track_id);
    EXPECT_EQ(2500, track.x);
    EXPECT_EQ(-5000, track.y);
    EXPECT_EQ(2000, track.w);
    EXPECT_EQ(4000, track.h);
    EXPECT_EQ(230, track.conf);
    EXPECT_EQ(250, track.distance_cm);
    EXPECT_EQ(1u, parser.frames);
    EXPECT_EQ(0u, parser.crc_errors);
}

TEST_F(VisionTrackerParserTest, EncoderMatchesPython) {
    vt_track_t track;

    memset(&track, 0, sizeof(track));
    track.seq         = 7;
    track.flags       = VT_TRACK_FLAG_VALID;
    track.track_id    = 3;
    track.x           = 2500;
    track.y           = -5000;
    track.w           = 2000;
    track.h           = 4000;
    track.conf        = 230;
    track.distance_cm = 250;

    uint8_t payload[VT_TRACK_PAYLOAD_LEN];
    uint8_t frame[VT_MAX_FRAME_LEN];
    vt_encode_track(&track, payload);
    ASSERT_EQ(sizeof(pythonTrackFrame), vt_encode_frame(VT_MSG_TRACK, payload, sizeof(payload), frame, sizeof(frame)));
    EXPECT_EQ(0, memcmp(frame, pythonTrackFrame, sizeof(pythonTrackFrame)));
}

TEST_F(VisionTrackerParserTest, RejectsCorruptedFrameAndRecovers) {
    std::vector<uint8_t> bytes = pythonFrame();

    bytes[8] ^= 0x40; // corrupt the payload
    append(bytes, trackFrame(1));

    EXPECT_EQ(1, feed(bytes));
    EXPECT_EQ(1, lastTrack.seq);
    EXPECT_EQ(1u, parser.crc_errors);
}

TEST_F(VisionTrackerParserTest, SkipsGarbageBetweenFrames) {
    std::vector<uint8_t> bytes;
    const uint8_t garbage1[] = { 0x00, 0xA5, 0x13, 0x5A, 0xFF };
    const uint8_t garbage2[] = { 0xA5, 0xA5 }; // repeated SYNC1 right before a frame

    bytes.insert(bytes.end(), garbage1, garbage1 + sizeof(garbage1));
    append(bytes, trackFrame(1));
    bytes.insert(bytes.end(), garbage2, garbage2 + sizeof(garbage2));
    append(bytes, trackFrame(2));

    EXPECT_EQ(2, feed(bytes));
    EXPECT_EQ(2, lastTrack.seq);
    EXPECT_EQ(-1234, lastTrack.x);
    EXPECT_EQ(4321, lastTrack.y);
}

TEST_F(VisionTrackerParserTest, RejectsOversizedLength) {
    std::vector<uint8_t> bytes;

    bytes.push_back(VT_SYNC1);
    bytes.push_back(VT_SYNC2);
    bytes.push_back(VT_MSG_TRACK);
    bytes.push_back(VT_MAX_PAYLOAD_LEN + 1);
    append(bytes, trackFrame(5));

    EXPECT_EQ(1, feed(bytes));
    EXPECT_EQ(5, lastTrack.seq);
    EXPECT_EQ(1u, parser.len_errors);
}

TEST_F(VisionTrackerParserTest, RecoversAfterTruncatedFrame) {
    // A truncated frame swallows the start of the next one (the parser does not
    // backtrack), so that frame is lost, but the parser must be back in sync for
    // the frame after it.
    std::vector<uint8_t> bytes = trackFrame(1);

    bytes.resize(10);
    append(bytes, trackFrame(2));
    append(bytes, trackFrame(3));

    EXPECT_GE(feed(bytes), 1);
    EXPECT_EQ(3, lastTrack.seq);
    EXPECT_GE(parser.crc_errors, 1u);
}

TEST_F(VisionTrackerParserTest, ParsesBackToBackFrames) {
    std::vector<uint8_t> bytes;

    for (uint8_t seq = 0; seq < 10; seq++) {
        append(bytes, trackFrame(seq));
    }

    EXPECT_EQ(10, feed(bytes));
    EXPECT_EQ(9, lastTrack.seq);
    EXPECT_EQ(10u, parser.frames);
    EXPECT_EQ(0u, parser.crc_errors);
}

TEST_F(VisionTrackerParserTest, AcceptsEmptyAndUnknownMessages) {
    uint8_t frame[VT_MAX_FRAME_LEN];
    uint8_t len = vt_encode_frame(0x42, NULL, 0, frame, sizeof(frame));

    ASSERT_EQ(VT_FRAME_OVERHEAD, len);
    EXPECT_EQ(1, feed(std::vector<uint8_t>(frame, frame + len)));
    EXPECT_EQ(0x42, lastMsgId);
    EXPECT_EQ(0, parser.len);
}

TEST_F(VisionTrackerParserTest, TrackPayloadLength) {
    uint8_t payload[VT_TRACK_PAYLOAD_LEN + 4];
    vt_track_t track;

    memset(payload, 0, sizeof(payload));
    EXPECT_FALSE(vt_decode_track(payload, VT_TRACK_PAYLOAD_LEN - 1, &track));
    EXPECT_TRUE(vt_decode_track(payload, VT_TRACK_PAYLOAD_LEN, &track));
    // longer payloads from newer companions are accepted
    EXPECT_TRUE(vt_decode_track(payload, sizeof(payload), &track));
}

TEST_F(VisionTrackerParserTest, EncodeFrameChecksSizes) {
    uint8_t payload[VT_MAX_PAYLOAD_LEN + 1];
    uint8_t frame[VT_MAX_FRAME_LEN + 1];

    memset(payload, 0, sizeof(payload));
    EXPECT_EQ(0, vt_encode_frame(VT_MSG_TRACK, payload, VT_MAX_PAYLOAD_LEN + 1, frame, sizeof(frame)));
    EXPECT_EQ(0, vt_encode_frame(VT_MSG_TRACK, payload, VT_TRACK_PAYLOAD_LEN, frame, VT_TRACK_PAYLOAD_LEN + VT_FRAME_OVERHEAD - 1));
    EXPECT_EQ(VT_MAX_FRAME_LEN, vt_encode_frame(VT_MSG_TRACK, payload, VT_MAX_PAYLOAD_LEN, frame, sizeof(frame)));
}

TEST_F(VisionTrackerParserTest, FcStatusRoundTrip) {
    vt_fc_status_t status;

    status.armed          = 2;
    status.flightmode     = 19;
    status.followme_state = 2;
    status.roll           = -1500;
    status.pitch          = 250;
    status.yaw = -17999;

    uint8_t payload[VT_FC_STATUS_PAYLOAD_LEN];
    uint8_t frame[VT_MAX_FRAME_LEN];
    vt_encode_fc_status(&status, payload);
    uint8_t len = vt_encode_frame(VT_MSG_FC_STATUS, payload, sizeof(payload), frame, sizeof(frame));
    ASSERT_EQ(VT_FC_STATUS_PAYLOAD_LEN + VT_FRAME_OVERHEAD, len);

    EXPECT_EQ(1, feed(std::vector<uint8_t>(frame, frame + len)));
    EXPECT_EQ(VT_MSG_FC_STATUS, lastMsgId);
    EXPECT_EQ(2, parser.payload[0]);
    EXPECT_EQ(19, parser.payload[1]);
    EXPECT_EQ(2, parser.payload[2]);
    EXPECT_EQ(-1500, (int16_t)(parser.payload[3] | (parser.payload[4] << 8)));
    EXPECT_EQ(250, (int16_t)(parser.payload[5] | (parser.payload[6] << 8)));
    EXPECT_EQ(-17999, (int16_t)(parser.payload[7] | (parser.payload[8] << 8)));
}
